import{_ as r,l,o as a,c,v as o,p as d,x as t,d as i,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Volcano 迭代器","description":"","frontmatter":{"title":"Volcano 迭代器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/volcano-iterator.md","filePath":"cs/volcano-iterator.md","lastUpdated":1789023840000}'),h={name:"cs/volcano-iterator.md"};function _(x,e,u,f,m,E){const n=l("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="volcano-迭代器" tabindex="-1">Volcano 迭代器 <a class="header-anchor" href="#volcano-迭代器" aria-label="Permalink to &quot;Volcano 迭代器&quot;">​</a></h1><div class="epigraph"><p>每个算子暴露 open / next / close；父亲拉儿子，一次一行。树是计划，时钟在 next 的调用栈上。</p><footer>—— 据 Graefe, Volcano—An Extensible and Parallel Query Evaluation System, TKDE 1994；Graefe 查询执行综述</footer></div><p>优化器在<a href="/cs/plan-regression">计划回归</a>封口。本课打开执行引擎：计划树已定，如何变成元组流。缺口是 Volcano（迭代器 / 拉模型）：统一接口让连接、选择、扫描可任意组装，并行用 exchange 插进同一接口。主干连接算法讲形状，不讲调用约定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物化模型：子算子跑完把整表放临时文件，父再读——简单，内存与延迟差。迭代器：父要一行就 <code>next()</code> 子，子再 <code>next()</code> 孙。流水线：选择可以在扫描吐行时立刻过滤，不必先落盘。缺口是<strong>控制流在算子里</strong>：阻塞算子（排序、哈希 build）在第一次 <code>next()</code> 时把输入吸干，之后才吐。</p><p><code>open</code> 分配状态，<code>close</code> 释放扫描与文件。错误与取消走 <code>close</code>。本课不把每家执行器的向量批次当 Volcano 否定；向量化下一课是同一接口上的批量化。</p><p><span class="marginnote">Graefe Volcano，IEEE TKDE 1994。并行：exchange 算子也实现 next，下面接其他线程的队列。本课点名，并行课再写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫描：<code>next</code> 返回下一槽化记录或空。选择：循环调用子 <code>next</code> 直到谓词真。NLJ：外层一行，内层 <code>open</code> 探测。哈希连接：build 在首次 next 阻塞完成，probe 流水。排序：阻塞。</p><p>资源：每个算子估内存；总内存超则算子内落盘（外部排序、Grace 哈希后课）。迭代器不自动解决内存，只规定谁拉谁。</p>',10)),(a(),d(p,null,{default:t(()=>[s(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%20next%22%5D%20--%3E%20P%5B%22%E7%88%B6%E7%AE%97%E5%AD%90%22%5D%0A%20%20P%20--%3E%20C1%5B%22%E5%AD%90%20next%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E5%AD%99%20next%22%5D%0A%20%20C2%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%A7%BD%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>解释器开销：每行多次虚调用，在 OLTP 宽行上可忽略，在 OLAP 窄扫描上占 CPU——向量化与编译执行要消灭的就是这条路径。NULL 与投影：迭代器携带的是槽或 RID+解引用；延迟物化后课决定何时读列。</p><p>取消查询：<code>close</code> 沿树向下，阻塞在排序的算子也要能被中断。这是执行契约，不是优化器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SIMD 批次。也不把火山模型与流式系统的 operator graph 混名——后者常推模型。编译执行会把迭代器树打成循环，接口在源码层消失，语义仍是拉。</p><p>后课默认：计划树按 open/next/close 解释执行；阻塞点在排序与哈希 build。向量化把 next 的粒度从行换成批。</p><p>Volcano 是组装与并行插入的约定，不是一种连接算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迭代器拉模型统一算子；阻塞算子在首次 next 物化输入。</li><li>每行调用开销是 OLAP 的 CPU 税。</li><li>向量化执行下一课：批处理摊掉解释器。</li><li>出处：Graefe, TKDE 1994；Graefe 执行综述。</li></ul>',9))])}const T=r(h,[["render",_]]);export{P as __pageData,T as default};
